/* Авторская практика ЕГЭ по магнитному полю. */
(() => {
  const variants = [
    ['Сила Ампера', 'Н', n => [
      `Проводник длиной 0,25 м расположен под углом 30° к полю с индукцией 0,8 Тл. По проводнику течёт ток ${n} А. Найди модуль силы Ампера в ньютонах.`, n/10,
      'Используй поперечную к проводнику составляющую поля B sin α.',
      `F = BIl sin α = 0,8 · ${n} · 0,25 · 0,5 = ${n/10} Н.`
    ]],
    ['Ток в проводнике', 'А', n => [
      `На проводник длиной 0,5 м, перпендикулярный полю 0,2 Тл, действует сила Ампера ${n/10} Н. Найди ток в амперах.`, n,
      'При угле 90° сила Ампера равна BIl.',
      `I = F/(Bl) = ${n/10}/(0,2 · 0,5) = ${n} А.`
    ]],
    ['Равновесие проводника', 'А', n => [
      `Горизонтальный проводник массой ${2*n} г и длиной 20 см перпендикулярен горизонтальному магнитному полю 0,5 Тл. Ток направлен так, что сила Ампера направлена вверх. Какой ток в амперах уравновешивает силу тяжести? Прими g = 10 м/с².`, n/5,
      'При равновесии mg = BIl. Переведи массу и длину в СИ.',
      `I = (${2*n}·10⁻³ · 10)/(0,5 · 0,2) = ${n/5} А.`
    ]],
    ['Сила Лоренца', 'мкН', n => [
      `Частица с зарядом ${n} нКл движется со скоростью 4 км/с под углом 30° к полю 0,5 Тл. Найди модуль магнитной силы в микроньютонах.`, n,
      'Магнитная сила равна |q|vB sin α.',
      `F = ${n}·10⁻⁹ · 4000 · 0,5 · 0,5 Н = ${n} мкН.`
    ]],
    ['Радиус орбиты иона', 'см', n => [
      `Ион массой 4·10⁻²⁶ кг и зарядом 2·10⁻¹⁹ Кл влетает перпендикулярно полю 0,2 Тл со скоростью ${10*n} км/с. Найди радиус круговой траектории в сантиметрах.`, n,
      'Магнитная сила сообщает центростремительное ускорение: |q|vB = mv²/r.',
      `r = mv/(|q|B) = (4·10⁻²⁶ · ${n}·10⁴)/(2·10⁻¹⁹ · 0,2) = ${n} см.`
    ]],
    ['Удельный заряд', '10⁶ Кл/кг', n => [
      `Частица движется по окружности радиусом 5 см со скоростью ${10*n} км/с в однородном поле 0,2 Тл. Поле перпендикулярно плоскости окружности. Найди модуль удельного заряда в единицах 10⁶ Кл/кг.`, n,
      'Из равенства |q|vB = mv²/r следует |q|/m = v/(Br).',
      `|q|/m = (${n}·10⁴)/(0,2 · 0,05) = ${n}·10⁶ Кл/кг.`
    ]],
    ['Период обращения', 'мкс', n => [
      `Ион с отношением m/|q| = ${n}·10⁻⁷ кг/Кл движется по окружности в однородном поле 0,2 Тл. Найди период в микросекундах. Прими π = 3,14.`, Number((3.14*n).toFixed(2)),
      'Подставь r = mv/(|q|B) в выражение T = 2πr/v.',
      `T = 2πm/(|q|B) = 2 · 3,14 · ${n}·10⁻⁷/0,2 с = ${Number((3.14*n).toFixed(2))} мкс.`
    ]],
    ['Движение по винтовой линии', 'см', n => [
      `Заряженная частица движется по винтовой линии в однородном магнитном поле. Период обращения 4 мкс, составляющая скорости вдоль поля ${5*n} км/с. Найди шаг винтовой линии в сантиметрах.`, 2*n,
      'Магнитная сила не меняет продольную составляющую скорости. Шаг равен перемещению вдоль поля за один период.',
      `h = v∥T = ${5*n}·10³ · 4·10⁻⁶ м = ${2*n} см.`
    ]],
    ['Фильтр скоростей', 'км/с', n => [
      `Пучок заряженных частиц летит перпендикулярно взаимно перпендикулярным полям. Электрическая и магнитная силы направлены навстречу друг другу. E = ${2*n} кВ/м, B = 0,2 Тл. При какой скорости в км/с частицы проходят без отклонения?`, 10*n,
      'Для прямолинейного движения электрическая и магнитная силы должны уравновешиваться.',
      `|q|E = |q|vB, откуда v = E/B = ${2*n}/0,2 = ${10*n} км/с.`
    ]],
    ['Действие поля на рамку', 'мН·м', n => [
      `Плоская катушка из ${n} витков площадью 50 см² каждый находится в однородном поле 0,4 Тл. Ток равен 2 А. Нормаль к виткам образует угол 30° с полем. Найди модуль момента сил в мН·м.`, 2*n,
      'Момент сил равен NBIS sin α, где α — угол между нормалью и полем.',
      `M = ${n} · 0,4 · 2 · 0,005 · 0,5 Н·м = ${2*n} мН·м.`
    ]]
  ];

  for (const [index, [title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 15; variant++) {
      const [question, answer, ...steps] = build(variant + 1);
      const category = index < 4 ? 363 : 410;
      tasks.push({
        id: `ege-physics-magnetism-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Магнитное поле',
        examTopic: 'physics-ege-magnetism',
        level: index < 2 ? 0 : index < 7 ? 1 : 2,
        title, question, unit, answer, steps,
        hints: ['Определи направления поля и скорости или тока.'],
        solution: steps.join(' '),
        review: {plan: steps[0]},
        source: {
          name: 'Решу ЕГЭ',
          id: category,
          type: 'тематический каталог',
          url: `https://phys-ege.sdamgia.ru/test?category_id=${category}&filter=all`,
          note: 'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

